CREATE TABLE IF NOT EXISTS oauth_clients (id text PRIMARY KEY, name text NOT NULL, type text NOT NULL, redirect_uris jsonb NOT NULL, allowed_scopes jsonb NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS external_identities (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), provider text NOT NULL, provider_subject text NOT NULL, email text NOT NULL, email_verified text NOT NULL, profile_snapshot jsonb NOT NULL, created_at timestamptz NOT NULL, last_login_at timestamptz NOT NULL, UNIQUE(provider, provider_subject));
CREATE TABLE IF NOT EXISTS oauth_authorization_codes (id text PRIMARY KEY, client_id text NOT NULL REFERENCES oauth_clients(id), user_id text NOT NULL REFERENCES users(id), redirect_uri text NOT NULL, scope text NOT NULL, code_challenge text NOT NULL, code_challenge_method text NOT NULL, state_hash text, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS desktop_sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), client_id text NOT NULL REFERENCES oauth_clients(id), active_tenant_id text REFERENCES tenants(id), access_token_hash text NOT NULL UNIQUE, refresh_token_hash text NOT NULL UNIQUE, device_name text, platform text, app_version text, access_expires_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, revoked_at timestamptz);
INSERT INTO oauth_clients (id, name, type, redirect_uris, allowed_scopes, status) VALUES ('plegat-desktop', 'Plegat Desktop', 'public', '["plegat://oauth/callback"]'::jsonb, '["openid","profile","email"]'::jsonb, 'active') ON CONFLICT (id) DO NOTHING;
